236	        } else {
237	            owners = this.clinicService.findAllOwners();
238	        }
239	        if (owners.isEmpty()) {
240	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
241	        }
242	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
243	    }
