346	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
347	    @Override
348	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
349	        String telephone = toE164(ownerFieldsDto.getTelephone());
350	        if (telephone == null) {
351	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
352	        }
353	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
354	        if (currentOwner == null) {
355	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
356	        }
357	        String email = ownerFieldsDto.getEmail();
358	        if (email != null && !EMAIL_PATTERN.matcher(email).matches()) {
359	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
360	        }
361	        currentOwner.setAddress(ownerFieldsDto.getAddress());
362	        currentOwner.setCity(ownerFieldsDto.getCity());
363	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
364	        currentOwner.setLastName(ownerFieldsDto.getLastName());
365	        currentOwner.setTelephone(telephone);
366	        currentOwner.setEmail(email == null ? null : email.toLowerCase());
367	        this.clinicService.saveOwner(currentOwner);
368	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
369	    }
