371	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
372	    @Transactional
373	    @Override
374	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
375	        Owner owner = this.clinicService.findOwnerById(ownerId);
376	        if (owner == null) {
377	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
378	        }
379	        this.clinicService.deleteOwner(owner);
380	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
381	    }
